"""Independent symbolic/numeric checks for the authored examples and boundary cases."""
import hashlib,json,pathlib
import sympy as s
ROOT=pathlib.Path(__file__).resolve().parents[1];x,y,z,t,r,theta,phi,rho=s.symbols('x y z t r theta phi rho',real=True);n=s.symbols('n',positive=True,integer=True);records=[]
def eq(name,a,b):
    a=s.sympify(a);b=s.sympify(b);assert s.simplify(a-b)==0,(name,a,b);records.append(dict(name=name,actual=str(a),expected=str(b),passed=True))
def yes(name,a):assert bool(a),name;records.append(dict(name=name,passed=True))
def dint(f,xx,lo,hi):return s.integrate(f,(xx,lo,hi))
def tri(f,L=1):return dint(dint(dint(f,z,0,L-x-y),y,0,L-x),x,0,L)
def main():
    a=s.Matrix([1,2,2]);eq('向量长度',a.norm(),3);eq('单位向量长度',(a/3).norm(),1)
    a=s.Matrix([1,0,1]);b=s.Matrix([0,1,1]);eq('夹角余弦',a.dot(b)/(a.norm()*b.norm()),s.Rational(1,2));eq('投影系数',a.dot(b)/b.dot(b),s.Rational(1,2))
    v=s.Matrix([1,0,0]).cross(s.Matrix([0,2,0]));eq('叉积x',v[0],0);eq('叉积y',v[1],0);eq('叉积z',v[2],2);eq('混合积体积',abs(v.dot(s.Matrix([0,0,3]))),6)
    eq('平面含指定点',(x+2*y-z+1).subs({x:1,y:0,z:2}),0);eq('点面距离',1/s.sqrt(1+4+1),1/s.sqrt(6));eq('几何练习点',(x-y+2*z-2).subs({x:1,y:1,z:1}),0)
    eq('几何练习距离',2/s.sqrt(1+1+4),2/s.sqrt(6));eq('方向向量保持直线点',s.Matrix([1+t,2*t,2-t]).subs(t,0).dot(s.Matrix([1,1,1])),3)
    f=x*y/(x*x+y*y);eq('二元极限沿横轴',s.limit(f.subs(y,0),x,0),0);eq('二元极限沿斜线',s.limit(f.subs(y,x),x,0),s.Rational(1,2))
    eq('可直接代入的极限',((x+y)/(x*x+y*y)).subs({x:1,y:1}),1);yes('夹逼因子范围',s.simplify((x*x+y*y)-x*x)==y*y)
    f=x*x*y+s.exp(y);eq('fx',s.diff(f,x),2*x*y);eq('fy',s.diff(f,y),x*x+s.exp(y));eq('点处fx',s.diff(f,x).subs({x:1,y:0}),0);eq('点处fy',s.diff(f,y).subs({x:1,y:0}),2)
    f=x*x*y**3;eq('fxx',s.diff(f,x,2),2*y**3);eq('fxy',s.diff(f,x,y),6*x*y*y);eq('交换混合偏导',s.diff(f,x,y),s.diff(f,y,x))
    f=x*x*y+s.sin(y)
    for name,expr,value in [('偏导练习x',s.diff(f,x),0),('偏导练习y',s.diff(f,y),2),('偏导练习xy',s.diff(f,x,y),2)]:eq(name,expr.subs({x:1,y:0}),value)
    eq('全微分dx系数',s.diff(x*x*y,x).subs({x:1,y:2}),4);eq('全微分dy系数',s.diff(x*x*y,y).subs({x:1,y:2}),1);eq('线性变化',4*s.Rational(1,100)-s.Rational(2,100),s.Rational(2,100))
    eq('精确变化',s.Rational(101,100)**2*s.Rational(198,100)-2,s.Rational(19798,1000000));eq('复合一参数',s.diff(t*t+t**4,t),2*t+4*t**3);eq('复合点处',s.diff(t*t+t**4,t).subs(t,1),6)
    eq('多参数复合x',3+2*4,11);eq('多参数复合y',3+1*4,7);eq('复合练习',2*1*3+2*4,14)
    F=x*x+y*y+z*z-9;eq('隐式点在曲面',F.subs({x:1,y:2,z:2}),0);eq('隐式x',(-s.diff(F,x)/s.diff(F,z)).subs({x:1,y:2,z:2}),-s.Rational(1,2));eq('隐式y',(-s.diff(F,y)/s.diff(F,z)).subs({x:1,y:2,z:2}),-1)
    eq('切平面含点',(x+2*y+2*z-9).subs({x:1,y:2,z:2}),0);eq('方向导数',s.Matrix([2,4]).dot(s.Matrix([s.Rational(3,5),s.Rational(4,5)])),s.Rational(22,5));eq('最大方向导数',s.sqrt(4+16),2*s.sqrt(5))
    f=x*x+y*y-2*x-4*y;eq('极值候选x',s.diff(f,x).subs(x,1),0);eq('极值候选y',s.diff(f,y).subs(y,2),0);eq('Hessian判别量',s.hessian(f,(x,y)).det(),4);eq('极小值',f.subs({x:1,y:2}),-5);eq('配方',f,(x-1)**2+(y-2)**2-5)
    for label,f in [('四次平方和',x**4+y**4),('四次平方差',x**4-y**4)]:eq(label+'二阶判别退化',s.hessian(f,(x,y)).det().subs({x:0,y:0}),0)
    eq('约束代入',x*(2-x),1-(x-1)**2);eq('约束最大值',x*(2-x).subs(x,1) if False else (x*(2-x)).subs(x,1),1);eq('端点值',(x*(2-x)).subs(x,0),0)
    eq('圆盘线性最大点',s.sqrt(2)/2+s.sqrt(2)/2,s.sqrt(2));eq('鞍点判别',s.hessian(x*x-y*y,(x,y)).det(),-4)
    eq('矩形二重积分',dint(dint(x+y,y,0,2),x,0,1),3);eq('三角形二重积分',dint(dint(x+y,y,0,1-x),x,0,1),s.Rational(1,3))
    eq('内层结果',dint(x+y,y,0,1-x),(1-x*x)/2);eq('换序以后结果',dint(x*s.exp(x*x),x,0,1),(s.E-1)/2)
    J=s.Matrix([[s.diff(r*s.cos(theta),q) for q in [r,theta]],[s.diff(r*s.sin(theta),q) for q in [r,theta]]]).det();eq('极坐标雅可比',J,r)
    eq('圆盘平方和积分',dint(dint(r**3,r,0,1),theta,0,2*s.pi),s.pi/2);eq('圆盘x平方积分',dint(dint(r**3*s.cos(theta)**2,r,0,1),theta,0,2*s.pi),s.pi/4)
    eq('四分之一圆盘面积',dint(dint(r,r,0,2),theta,0,s.pi/2),s.pi);eq('四分之一圆盘平方和',dint(dint(r**3,r,0,2),theta,0,s.pi/2),2*s.pi)
    eq('长方体体积',dint(dint(dint(1,z,0,3),y,0,2),x,0,1),6);eq('长方体高度积分',dint(dint(dint(z,z,0,3),y,0,2),x,0,1),9)
    eq('单位四面体体积',tri(1),s.Rational(1,6));eq('圆柱平方和积分',dint(dint(dint(r**3,z,0,2),r,0,1),theta,0,2*s.pi),s.pi)
    mapping=s.Matrix([rho*s.sin(phi)*s.cos(theta),rho*s.sin(phi)*s.sin(theta),rho*s.cos(phi)]);jac=s.simplify(mapping.jacobian((rho,phi,theta)).det());eq('球坐标雅可比',jac,rho*rho*s.sin(phi))
    eq('半径二球体积',dint(dint(dint(rho*rho*s.sin(phi),rho,0,2),phi,0,s.pi),theta,0,2*s.pi),32*s.pi/3)
    eq('四面体x力矩',tri(x),s.Rational(1,24));eq('四面体重心',tri(x)/tri(1),s.Rational(1,4));eq('球壳体积',4*s.pi/3*(8-1),28*s.pi/3);eq('三重积分练习',tri(1,2),s.Rational(4,3))
    speed=s.sqrt(s.diff(s.cos(t),t)**2+s.diff(s.sin(t),t)**2);eq('单位圆速度',speed,1);eq('上半圆弧长',dint(speed,t,0,s.pi),s.pi);eq('上半圆y加权',dint(s.sin(t)*speed,t,0,s.pi),2)
    eq('直线第二类',dint(2*t,t,0,1),1);eq('圆周参数积分',dint(s.sin(t)**2+s.cos(t)**2,t,0,2*s.pi),2*s.pi)
    eq('Green被积式',s.diff(x,x)-s.diff(-y,y),2);eq('Green练习半径二',2*s.pi*4,8*s.pi)
    potential=x*x*y;eq('势函数x',s.diff(potential,x),2*x*y);eq('势函数y',s.diff(potential,y),x*x);eq('路径无关例题',potential.subs({x:1,y:2})-potential.subs({x:0,y:0}),2)
    P=-y/(x*x+y*y);Q=x/(x*x+y*y);eq('有洞反例交叉偏导相等',s.diff(P,y)-s.diff(Q,x),0)
    eq('斜面面积因子',s.sqrt(1+1+1),s.sqrt(3));eq('斜面常场向上通量',s.Matrix([0,0,1]).dot(s.Matrix([-1,-1,1])),1);eq('斜面径向场通量',-x-y+(x+y),0)
    eq('径向场散度',s.diff(x,x)+s.diff(y,y)+s.diff(z,z),3);eq('球面通量',3*4*s.pi/3,4*s.pi);eq('上半球补面',0-(-s.pi),s.pi);eq('Stokes旋度z',s.diff(x,x)-s.diff(-y,y),2);eq('立方体通量',3*1,3)
    eq('几何级数n1',s.summation(s.Rational(1,2)**n,(n,1,s.oo)),1);eq('几何级数n0',s.summation(s.Rational(1,2)**n,(n,0,s.oo)),2)
    eq('比较极限',s.limit(n/s.sqrt(n*n+1),n,s.oo),1);eq('阶乘比值',s.simplify((2**(n+1)/s.factorial(n+1))/(2**n/s.factorial(n))),2/(n+1));eq('根值极限',s.limit(n/(2*n+1),n,s.oo),s.Rational(1,2))
    eq('交错误差界',1/s.Integer(101),s.Rational(1,101));yes('误差小于百分之一',s.Rational(1,101)<s.Rational(1,100));eq('级数练习比值',s.limit((n+1)/(3*n),n,s.oo),s.Rational(1,3))
    an=(x-1)**n/(n*2**n);ratio=s.simplify((an.subs(n,n+1)/an));eq('幂级数比值代数',ratio,(x-1)*n/(2*(n+1)))
    eq('幂级数左端项',an.subs(x,-1),(-1)**n/n);eq('幂级数右端项',an.subs(x,3),1/n);eq('等比求导',s.diff(1/(1-x),x),1/(1-x)**2)
    eq('等比逐项积分',s.diff(-s.log(1-x),x),1/(1-x));eq('exp平方六次系数',s.expand(s.series(s.exp(x*x),x,0,8).removeO()).coeff(x,6),s.Rational(1,6));eq('展开极限',s.limit((s.exp(x)-1-x)/(x*x),x,0),s.Rational(1,2))
    for N in range(1,7):eq('Fourier正弦系数'+str(N),2/s.pi*dint(x*s.sin(N*x),x,0,s.pi),2*(-1)**(N+1)/s.Integer(N))
    eq('Fourier零常数',dint(x,x,-s.pi,s.pi)/s.pi,0);eq('Fourier跳跃平均',(s.pi-s.pi)/2,0);eq('幂级数练习左端',((x-2)/3)**n .subs(x,-1) if False else (((x-2)/3)**n).subs(x,-1),(-1)**n);eq('幂级数练习右端',(((x-2)/3)**n).subs(x,5),1)
    course=ROOT/'public/course.json';report=dict(allPassed=True,checks=len(records),scope='independent symbolic calculations, Jacobians, sample coefficients and boundary examples; not a proof of theorems or a substitute for condition review',courseSha256=hashlib.sha256(course.read_bytes()).hexdigest(),records=records)
    (ROOT/'build/math-verification.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf8');print('MATH_VERIFIED',len(records),'checks',flush=True)
if __name__=='__main__':main()
